using System;

class Player
{
    static void Main()
    {
        int h = int.Parse(Console.ReadLine().Trim());
        string stock = Console.ReadLine();
        int c = 0, n = 0;
        for (int i = 0; i < stock.Length; i++)
        {
            if (stock[i] != '.') { c = i; n = stock[i] - '0'; }
        }

        char[][] board = new char[h][];
        for (int i = 0; i < h; i++) board[i] = Console.ReadLine().ToCharArray();

        for (int b = 0; b < n; b++)
        {
            int col = c;
            for (int row = 0; row < h; row++)
            {
                char peg = board[row][col];
                if (peg == '.') continue;
                board[row][col] = peg == '<' ? '>' : '<';
                col += peg == '<' ? -1 : 1;
            }
            Console.WriteLine(col);
        }
    }
}
